import{_ as o,a0 as l,w as p,s as r,I as n,x as e,a1 as a,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 和 FreeDOS 之間複製文件 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 和 FreeDOS 之間複製文件 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 和 FreeDOS 之間複製文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 和 FreeDOS 之間複製文件 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210624 Copy files between Linux and FreeDOS","title":"在 Linux 和 FreeDOS 之間複製文件","tag":"202107","desc":""},"relativePath":"202107/20210624 Copy files between Linux and FreeDOS.md","filePath":"[post].md"}'),u={name:"202107/20210624 Copy files between Linux and FreeDOS.md"};function g(m,s,x,f,k,b){const t=l("Link");return p(),r("div",null,[s[29]||(s[29]=n("h1",{id:"在-linux-和-freedos-之間複製文件",tabindex:"-1"},[e("在 Linux 和 FreeDOS 之間複製文件 "),n("a",{class:"header-anchor",href:"#在-linux-和-freedos-之間複製文件","aria-label":"Permalink to “在 Linux 和 FreeDOS 之間複製文件”"},"​")],-1)),s[30]||(s[30]=n("blockquote",null,[n("p",null,"下面是我如何在我的 FreeDOS 虛擬機和 Linux 桌面系統之間傳輸文件。")],-1)),s[31]||(s[31]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/04/181327bfvv3mmzby9z2dpr.jpg",alt:""})],-1)),s[32]||(s[32]=n("p",null,"我運行 Linux 作為我的主要操作系統，我在一個虛擬機中啓動 FreeDOS。大多數時候，我使用 QEMU 作為我的 PC 模擬器，但有時我會用 GNOME Boxes（它使用 QEMU 作為後端虛擬機）或用 VirtualBox 運行其他實驗。",-1)),n("p",null,[s[1]||(s[1]=e("我喜歡玩經典的 DOS 遊戲，有時我也會調出一個最喜歡的 DOS 應用。我在管理信息系統（MIS）課上講計算機的歷史，有時我會用 FreeDOS 和一個傳統的 DOS 應用錄製一個演示，比如 As-Easy-As（我最喜歡的 DOS 電子表格，曾經作為“共享軟件”發佈，但現在可以 ",-1)),a(t,{href:"http://www.triusinc.com/forums/viewtopic.php?t=10"},{default:i(()=>[...s[0]||(s[0]=[e("從 TRIUS 公司免費獲得",-1)])]),_:1}),s[2]||(s[2]=e("）。",-1))]),s[33]||(s[33]=n("p",null,"但是以這種方式使用 FreeDOS 意味着我需要在我的 FreeDOS 虛擬機和我的 Linux桌 面系統之間傳輸文件。讓我來展示是如何做到這一點的。",-1)),s[34]||(s[34]=n("h3",{id:"用-guestmount-訪問鏡像",tabindex:"-1"},[e("用 guestmount 訪問鏡像 "),n("a",{class:"header-anchor",href:"#用-guestmount-訪問鏡像","aria-label":"Permalink to “用 guestmount 訪問鏡像”"},"​")],-1)),n("p",null,[s[4]||(s[4]=e("我曾經通過計算第一個 DOS 分區的偏移量來訪問我的虛擬磁盤鏡像，然後用正確的選項組合來調用 Linux 的 ",-1)),s[5]||(s[5]=n("code",null,"mount",-1)),s[6]||(s[6]=e(" 命令來匹配這個偏移量。這總是很容易出錯，而且不是很靈活。幸運的是，有一個更簡單的方法可以做到這一點。來自 ",-1)),a(t,{href:"https://libguestfs.org/"},{default:i(()=>[...s[3]||(s[3]=[e("libguestfs-tools",-1)])]),_:1}),s[7]||(s[7]=e(" 包的 ",-1)),s[8]||(s[8]=n("code",null,"guestmount",-1)),s[9]||(s[9]=e(" 程序可以讓你從 Linux 中訪問或 ",-1)),s[10]||(s[10]=n("em",null,"掛載",-1)),s[11]||(s[11]=e(" 虛擬磁盤鏡像。你可以在 Fedora 上用這個命令安裝 ",-1)),s[12]||(s[12]=n("code",null,"libguestfs-tools",-1)),s[13]||(s[13]=e("：",-1))]),s[35]||(s[35]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum install libguestfs-tools libguestfs</span></span></code></pre></div><p>使用 <code>guestmount</code> 並不像從 GNOME 文件管理器中雙擊文件那麼簡單，但命令列的使用並不難。<code>guestmount</code> 的基本用法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ guestmount -a image -m device mountpoint</span></span></code></pre></div><p>在這個用法中，<code>image</code> 是要使用的虛擬磁盤鏡像。在我的系統中，我用 <code>qemu-img</code> 命令創建了 QEMU 虛擬磁盤鏡像。<code>guestmount</code> 程序可以讀取這種磁盤鏡像格式，以及 GNOME Boxes 使用的 QCOW2 鏡像格式，或者 VirtualBox 使用的 VDI 鏡像格式。</p><p><code>device</code> 選項表示虛擬磁盤上的分區。想像一下，把這個虛擬磁盤當作一個真正的硬盤使用。你可以用 <code>/dev/sda1</code> 訪問第一個分區，用 <code>/dev/sda2</code> 訪問第二個分區，以此類推。這就是 <code>guestmount</code> 的語法。默認情況下，FreeDOS 1.3 RC4 在一個空的驅動器上創建了一個分區，所以訪問這個分區的時候要用 <code>/dev/sda1</code>。</p><p>而 <code>mountpoint</code> 是在你的本地 Linux 系統上“掛載” DOS 文件系統的位置。我通常會創建一個臨時目錄來工作。你只在訪問虛擬磁盤時需要掛載點。</p><p>綜上所述，我使用這組命令從 Linux 訪問我的 FreeDOS 虛擬磁盤鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /tmp/freedos</span></span>
<span class="line"><span>$ guestmount -a freedos.img -m /dev/sda1 /tmp/freedos</span></span></code></pre></div><p>之後，我可以通過 <code>/tmp/freedos</code> 目錄訪問我的 FreeDOS 文件，使用 Linux 上的普通工具。我可以在命令列中使用 <code>ls /tmp/freedos</code>，或者使用桌面文件管理器打開 <code>/tmp/freedos</code> 掛載點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /tmp/freedos</span></span>
<span class="line"><span>total 216</span></span>
<span class="line"><span>drwxr-xr-x. 5 root root 8192 May 10 15:53 APPS</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 85048 Apr 30 07:54 COMMAND.COM</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root  103 May 13 15:48 CONFIG.SYS</span></span>
<span class="line"><span>drwxr-xr-x. 5 root root 8192 May 15 16:52 DEVEL</span></span>
<span class="line"><span>drwxr-xr-x. 2 root root 8192 May 15 13:36 EDLIN</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 1821 May 10 15:57 FDAUTO.BAT</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root  740 May 13 15:47 FDCONFIG.SYS</span></span>
<span class="line"><span>drwxr-xr-x. 10 root root 8192 May 10 15:49 FDOS</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 46685 Apr 30 07:54 KERNEL.SYS</span></span>
<span class="line"><span>drwxr-xr-x. 2 root root 8192 May 10 15:57 SRC</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 3190 May 16 08:34 SRC.ZIP</span></span>
<span class="line"><span>drwxr-xr-x. 3 root root 8192 May 11 18:33 TEMP</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/gnome-file-manager.png" alt="GNOME file manager" title="Using GNOME file manager to access the virtual disk"></p><p><em>使用 GNOME 文件管理器來訪問虛擬磁盤</em></p><p>例如，要從我的 Linux <code>projects</code> 目錄中複製幾個 C 源文件到虛擬磁盤鏡像上的 <code>C:\\SRC</code>，以便我以後能在 FreeDOS 下使用這些文件，我可以使用 Linux <code>cp</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /home/jhall/projects/*.c /tmp/freedos/SRC</span></span></code></pre></div><p>虛擬驅動器上的文件和目錄在技術上是不分大小寫的，所以你可以用大寫或小寫字母來引用它們。然而，我發現使用所有大寫字母來輸入 DOS 文件和目錄更為自然。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /tmp/freedos</span></span>
<span class="line"><span>APPS     CONFIG.SYS EDLIN    FDCONFIG.SYS KERNEL.SYS SRC.ZIP</span></span>
<span class="line"><span>COMMAND.COM DEVEL    FDAUTO.BAT FDOS     SRC     TEMP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /tmp/freedos/EDLIN</span></span>
<span class="line"><span>EDLIN.EXE MAKEFILE.OW</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /tmp/freedos/edlin</span></span>
<span class="line"><span>EDLIN.EXE MAKEFILE.OW</span></span></code></pre></div><h3 id="用-guestmount-卸載" tabindex="-1">用 guestmount 卸載 <a class="header-anchor" href="#用-guestmount-卸載" aria-label="Permalink to “用 guestmount 卸載”">​</a></h3><p>在你再次在虛擬機中使用虛擬磁盤鏡像之前，你應該總是先 <em>卸載</em>。如果你在運行 QEMU 或 VirtualBox 時讓鏡像掛載，你有可能弄亂你的文件。</p><p>與 <code>guestmount</code> 配套的命令是 <code>guestunmount</code>，用來卸載磁盤鏡像。只要給出你想卸載的掛載點就可以了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ guestunmount /tmp/freedos</span></span></code></pre></div><p>請注意命令拼寫與 Linux 的 <code>umount</code> 稍有不同。</p><hr>`,22)),n("p",null,[s[15]||(s[15]=e("via: ",-1)),a(t,{href:"https://opensource.com/article/21/6/copy-files-linux-freedos"},{default:i(()=>[...s[14]||(s[14]=[e("https://opensource.com/article/21/6/copy-files-linux-freedos",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=e("作者：",-1)),a(t,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[16]||(s[16]=[e("Jim Hall",-1)])]),_:1}),s[21]||(s[21]=e(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[17]||(s[17]=[e("lujun9972",-1)])]),_:1}),s[22]||(s[22]=e(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[18]||(s[18]=[e("geekpi",-1)])]),_:1}),s[23]||(s[23]=e(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[19]||(s[19]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[26]||(s[26]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[24]||(s[24]=[e("LCTT",-1)])]),_:1}),s[27]||(s[27]=e(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...s[25]||(s[25]=[e("Linux中國",-1)])]),_:1}),s[28]||(s[28]=e(" 榮譽推出",-1))])])}const D=o(u,[["render",g]]);export{C as __pageData,D as default};
